alter table public.takanodai_timetable
  drop constraint takanodai_timetable_direction_departure_time_key;

alter table public.takanodai_timetable
  add column service_day text not null default 'weekday'
  check (service_day in ('weekday', 'saturday'));

alter table public.takanodai_timetable
  add constraint takanodai_timetable_service_day_direction_departure_time_key
  unique (service_day, direction, departure_time);

